        dark_track: u32,
    ) -> (i32, i32) {
        let x = track.left() + px(8.5);
        let rows: Vec<i32> = (0..track.size.height.as_f32() as i32)
            .filter(|y| !same(frame.at(point(x, track.top() + px(*y as f32 + 0.5))), dark_track))
            .collect();
        (*rows.first().unwrap(), *rows.last().unwrap())
    }

