                // track below it, read down the column's middle.
                let rows: Vec<i32> = (0..height)
                    .filter(|y| !same(at(8., *y as f32, track), track_color))
                    .collect();
                let (first, last) = (rows[0], *rows.last().unwrap());
                assert_eq!(first, 0, "{case}: the thumb isn't at the top");
