    fn render_running(&self, cx: &mut Context<Self>) -> AnyElement {
        let Holding::Running {
            target,
            rows,
            locked,
            ..
        } = &self.holding
        else {
            return div().into_any_element();
        };
        let theme = cx.theme();
        let (mono, well) = (
            theme.mono_font_family.clone(),
            crate::theme::palette(cx).well,
        );
        let this = cx.entity().downgrade();
        let render: RenderRow = Rc::new({
            let this = this.clone();
            let mono = mono.clone();
            move |ix, _, cx| {
                let line = this
                    .upgrade()
                    .and_then(|this| match &this.read(cx).holding {
                        Holding::Running { lines, .. } => lines.get(ix).cloned(),
                        _ => None,
                    })
                    .unwrap_or_default();
                let highlights = line.highlights(cx);
                div()
                    .px_4()
                    .text_sm()
                    .font_family(mono.clone())
                    .child(StyledText::new(line.text).with_highlights(highlights))
                    .into_any_element()
            }
        });
        let toggle: SetLock = Rc::new(move |lock, _, cx| {
            this.update(cx, |this, cx| {
                if let Holding::Running { locked, rows, .. } = &mut this.holding {
                    *locked = lock;
                    if lock {
                        rows.scroll_to_end();
                    }
                }
                cx.notify();
            })
            .ok();
        });
        let log = div()
            .id("run-output")
            .size_full()
            .py(BODY_INSET)
            .bg(gpui_kit::rgb(well))
            .child(rows.element(render));
        let log = gpui_kit::TestSupportExt::test_support(log);
        v_flex()
            .size_full()
            .child(
                div()
                    .flex_none()
                    .px_4()
                    .py_2()
                    .border_b_1()
                    .border_color(theme.border)
                    .text_sm()
                    .font_family(mono)
                    .text_color(theme.muted_foreground)
                    .child(target.command.clone()),
            )
            .child(div().flex_1().min_h_0().child(scrollbar::with_scrollbar(
                "run-output",
                rows,
                log,
                true,
                Some((*locked, toggle)),
                cx,
            )))
            .into_any_element()
    }
}

